/* The C++ reference shell (/api/, overrides/api.html).
 *
 * The reference itself is generated by Doxygen into /api/ref/ and shown in a
 * frame on that page, so it is surrounded by the site's own header, tabs,
 * search, repository widget and Download modal instead of by a copy of them.
 * The cost of a frame is that the address bar stops following the reader, and
 * this script pays it: every page the frame reaches is written back to the
 * shell's own URL as `?p=<page>.html#<anchor>`, and that URL, pasted or
 * bookmarked, opens the same page. A generated page opened directly (a search
 * result, a link from elsewhere in the docs) redirects into the shell itself;
 * see tools/docs-hooks/doxygen-header.html.
 *
 * The listeners are installed once on `window`/`document`, which survive
 * Material's instant navigation. The per page part (finding the frame and
 * pointing it at `?p=`) re-runs on every page change through Material's
 * `document$` observable, falling back to a plain DOM ready when the theme's
 * bundle is not there.
 */
(function () {
  "use strict";

  var FRAME_ID = "synqt-api-frame";
  var MESSAGE = "synqt-api-nav";

  // A generated page name, and nothing else: no scheme, no host, no leading
  // slash, no `..`. `?p=` comes from the address bar, so it decides what the
  // frame loads and is treated as untrusted input; anything that does not look
  // like a page of the reference falls back to its landing page.
  var PAGE = /^[A-Za-z0-9][\w.-]*(\/[A-Za-z0-9][\w.-]*)*\.html$/;

  function requestedPage() {
    var match = /[?&]p=([^&#]*)/.exec(window.location.search);
    if (!match) return "index.html";
    var page;
    try {
      page = decodeURIComponent(match[1]);
    } catch (e) {
      return "index.html";
    }
    if (!PAGE.test(page) || page.indexOf("..") !== -1) return "index.html";
    return page;
  }

  function frameElement() {
    return document.getElementById(FRAME_ID);
  }

  // The frame's `data-src` in the template is the reference's landing page, so
  // its directory is the base every other page is resolved against. Reading it
  // from the element rather than hard coding "/api/ref/" keeps this working when
  // the site is published under a sub path.
  function baseUrl(frame) {
    var declared = frame.getAttribute("data-src") || frame.src;
    return new URL(".", new URL(declared, window.location.href)).href;
  }

  // Doxygen remembers the last tree entry a reader clicked and reselects that one
  // on every page it draws, instead of the page on screen. The reference no longer
  // keeps that memory (tools/docs-hooks/doxygen.py) and clears it as each of its
  // pages loads (tools/docs-hooks/doxygen-header.html), but a browser still
  // holding a cached copy of the reference from before those two runs the old code
  // and stays pinned to whichever entry it remembers. This is the way out that a
  // cached copy cannot get in front of: the reference is served from this origin,
  // so its storage is this page's storage, and the frame is not pointed at
  // anything until after this has run.
  var NAVPATH = "doxygen_navpath";

  function forgetTreeMemory() {
    try {
      window.localStorage.removeItem(NAVPATH);
      window.sessionStorage.removeItem(NAVPATH);
    } catch (e) {
      // Storage can be disabled outright, in which case there is nothing stored.
    }
    document.cookie = NAVPATH + "=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/";
  }

  // Clearing it once, as the reference opens, is not enough, and this is the whole of
  // the bug it took three attempts to place: an older page writes the entry back every
  // time a tree link is clicked. The tree is right on that page, because the entry and
  // the page agree, and wrong on every page reached from the content pane afterwards,
  // because nothing there updates it. That is exactly what a reader sees: the tree
  // follows a click in the tree, and ignores a click in the page.
  //
  // So clear it on the way out of each page as well. The listener is on the capture
  // phase of the frame's own document, which runs before the click reaches the link
  // whose handler would store it, and it is installed as each page announces itself,
  // which is the earliest this side can reach a document it did not load.
  function guardFrameDocument(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (e) {
      return; // Only reachable for a cross origin document, which this frame never holds.
    }
    if (!doc || doc.synqtTreeGuarded) return;
    doc.synqtTreeGuarded = true;
    doc.addEventListener("click", forgetTreeMemory, true);
  }

  function framePath(frame) {
    try {
      var here = frame.contentWindow.location;
      return here.href.slice(baseUrl(frame).length) || "index.html";
    } catch (e) {
      // Only reachable if the frame ever held a cross origin document, which
      // the reference never does; treat it as "unknown" and re-point the frame.
      return null;
    }
  }

  function show(frame, page, hash) {
    var wanted = new URL(page + hash, baseUrl(frame)).href;
    if (frame.src !== wanted) frame.src = wanted;
  }

  function sync() {
    var frame = frameElement();
    if (!frame) return;
    forgetTreeMemory();
    show(frame, requestedPage(), window.location.hash);
  }

  // The reference's own page reports where it landed. Rewrite the shell's URL
  // (replace, not push: the frame's navigation is already one history entry, and
  // a second one would need two clicks of Back to leave a page) and take the
  // page's title, so a bookmark and a browser tab both name the page the reader
  // is actually on.
  function onNavigated(detail) {
    var page = String(detail.page || "");
    if (!PAGE.test(page) || page.indexOf("..") !== -1) return;
    var hash = String(detail.hash || "");
    if (hash && !/^#[\w-]+$/.test(hash)) hash = "";

    var url = window.location.pathname;
    if (page !== "index.html") url += "?p=" + encodeURIComponent(page);
    url += hash;
    try {
      window.history.replaceState(window.history.state, "", url);
    } catch (e) {
      // A history call can throw only on an opaque origin (a `file://` copy of
      // the site); the frame still works, the address bar just stops following.
    }
    if (detail.title) document.title = String(detail.title);
  }

  window.addEventListener("message", function (event) {
    if (event.origin !== window.location.origin) return;
    var data = event.data;
    if (!data || data.type !== MESSAGE) return;
    var frame = frameElement();
    if (!frame) return;
    // A page announces itself from its <head>, several scripts before its tree is
    // built, so an older page still reading the entry finds nothing left of it.
    forgetTreeMemory();
    guardFrameDocument(frame);
    onNavigated(data);
  });

  // Back and Forward move the frame themselves (its own history entries are part
  // of the session history), and the load that follows reports the new page
  // through the message above. This only has to catch the case where the shell's
  // own URL changed without the frame following, which is what happens when the
  // reader edits `?p=` or arrives from a link on another page of the site.
  window.addEventListener("popstate", function () {
    var frame = frameElement();
    if (!frame) return;
    var page = requestedPage();
    if (framePath(frame) !== page + window.location.hash) {
      show(frame, page, window.location.hash);
    }
  });

  // Straight away as well as on every page change: this script is at the end of
  // the body, so on a full load of the shell the frame is already parsed and can
  // start fetching the reference now rather than one event later. It does nothing
  // on any other page, and setting the same page twice is not a second load.
  sync();

  if (window.document$ && typeof window.document$.subscribe === "function") {
    window.document$.subscribe(sync);
  } else if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", sync);
  }
})();
